ENV = {
    **os.environ,
    "OMP_NUM_THREADS": "1",
    "MKL_NUM_THREADS": "1",
    "OPENBLAS_NUM_THREADS": "1",
    "NUMEXPR_NUM_THREADS": "1",
    "TOKENIZERS_PARALLELISM": "false",
    "PYTHONDONTWRITEBYTECODE": "1",
}


def export(name: str) -> Path:
    target = WORK / name
    if target.exists():
        shutil.rmtree(target)
    target.mkdir(parents=True)
    archive = WORK / f"{name}.tar"
    subprocess.run(["git", "-C", str(REPO), "archive", "-o", str(archive), "HEAD"], check=True)
    with tarfile.open(archive) as tar:
        tar.extractall(target, filter="data")
    archive.unlink()
    return target


def apply(root: Path, edits: list[dict[str, str]]) -> None:
    for edit in edits:
        path = root / edit["file"]
        raw = path.read_bytes().decode("utf-8")
        crlf = "\r\n" in raw
        anchor, replacement = edit["anchor"], edit["replacement"]
        if crlf:
            anchor, replacement = anchor.replace("\n", "\r\n"), replacement.replace("\n", "\r\n")
        count = raw.count(anchor)
        if count != 1:
            raise SystemExit(f"anchor matched {count} times in {edit['file']}: {edit['anchor']!r}")
        path.write_bytes(raw.replace(anchor, replacement).encode("utf-8"))
        py_compile.compile(str(path), doraise=True)


def run_nodes(root: Path, nodes: list[str]) -> tuple[int, str, dict[str, str]]:
    env = {**ENV, "PYTHONPATH": f"{root / 'src'}:{root / 'tests'}"}
    origin = subprocess.run(
        [str(PY), "-c", "import xlm; print(xlm.__file__)"],
        cwd=root, env=env, capture_output=True, text=True, check=True,
    ).stdout.strip()
    if not origin.startswith(str(root)):
        raise SystemExit(f"xlm imported from {origin}, not the export")
    proc = subprocess.run(
        [str(PY), "-m", "pytest", *nodes, "-n", "0", "-p", "no:cacheprovider", "-rfE",
         "--junitxml", str(root / "junit.xml")],
        cwd=root, env=env, capture_output=True, text=True, timeout=900,
    )
    import xml.etree.ElementTree as ET

    outcomes: dict[str, str] = {}
    for case in ET.parse(root / "junit.xml").iter("testcase"):
        name = case.get("classname", "").replace(".", "/") + ".py::" + case.get("name", "")
        failure = case.find("failure")
        error = case.find("error")
        if error is not None:
            outcomes[name] = "ERROR: " + (error.get("message") or "")[:200]
        elif failure is not None:
            outcomes[name] = "FAILURE: " + (failure.get("message") or "")[:200]
        else:
            outcomes[name] = "passed"
    return proc.returncode, proc.stdout + proc.stderr, outcomes


def main() -> None:
    started = time.time()
    WORK.mkdir(parents=True, exist_ok=True)
    head = subprocess.run(
        ["git", "-C", str(REPO), "rev-parse", "HEAD"], capture_output=True, text=True, check=True
    ).stdout.strip()
    all_nodes = sorted({n for m in MUTANTS for n in m["nodes"]})
    control_root = export("control")
    code, out, _ = run_nodes(control_root, all_nodes)
    control = {"exit": code, "summary": out.strip().splitlines()[-1], "nodes": len(all_nodes)}
    if code != 0:
        print(out)
        raise SystemExit("unmutated control is not green")
    results = []
    for mutant in MUTANTS:
        root = export(f"m{mutant['id']}")
        apply(root, mutant["edits"])
        code, out, outcomes = run_nodes(root, mutant["nodes"])
        failed = sorted(set(re.findall(r"^FAILED (\S+)", out, flags=re.M)))
        broken = bool(re.search(r"(ImportError|ModuleNotFoundError|SyntaxError|ERROR collecting|^ERROR )", out, flags=re.M))
        assertions = [line for line in out.splitlines() if line.startswith("E ") and ("assert" in line or "DID NOT RAISE" in line or "Error" in line)]
        failures = [v for v in outcomes.values() if v != "passed"]
        asserted = len(failures) == len(mutant["nodes"]) and all(
            v.startswith("FAILURE: ") and ("assert" in v or "DID NOT RAISE" in v) for v in failures
        )
        killed = code == 1 and failed == sorted(mutant["nodes"]) and not broken and asserted
        results.append(
            {
                "id": mutant["id"],
                "label": mutant["label"],
                "edits": mutant["edits"],
                "nodes": mutant["nodes"],
                "exit": code,
                "failed_nodes": failed,
                "assertion_failures": asserted,
                "import_or_syntax_error": broken,
                "assertions": assertions[:6],
                "junit_outcomes": outcomes,
                "result": "KILLED" if killed else "SURVIVED_OR_INVALID",
            }
        )
        print(f"mutant {mutant['id']}: {'KILLED' if killed else 'NOT KILLED'} exit={code} failed={failed}")
        if not killed:
            print(out[-4000:])
        shutil.rmtree(root)
    shutil.rmtree(control_root)
    source = Path(__file__).read_bytes()
    record = {
        "label": "P35 M5 scratch mutation run (mutant code never committed)",
        "tested_head": head,
        "runner_sha256": hashlib.sha256(source).hexdigest(),
        "runner_source": source.decode("utf-8"),
        "environment": f"Linux cloud container, Python {sys.version.split()[0]}, base+dev lock, no torch",
        "kill_rule": "pytest exit 1; exactly the listed nodes FAILED; each on an assertion or "
        "pytest.raises DID NOT RAISE; no import/syntax/collection error; anchors matched exactly once; "
        "py_compile passed; xlm imported from the export",
        "control": control,
        "mutants": results,
        "seconds": round(time.time() - started, 1),
    }
    out_path = Path(sys.argv[1])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(record, indent=1) + "\n", encoding="utf-8")
    print(f"control {control}; {sum(r['result'] == 'KILLED' for r in results)}/{len(results)} killed; {record['seconds']}s")


if __name__ == "__main__":
    main()

